function escapeRe(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** Handlebars-style fallback: {{#if var}} … {{else}} somewhere in the email. */
function hasIfElse(raw, fullText) {
  const varName = raw.replace(/\{\{|\}\}/g, '').trim().split(/\s+/).pop();
  return new RegExp(`\\{\\{#if\\s+${escapeRe(varName)}\\s*\\}\\}`, 'i').test(fullText)
      && /\{\{else\}\}/i.test(fullText);
}

