function findAll(text, re) {
  const fresh = new RegExp(re.source, re.flags);
  const matches = [];
  let m;
  while ((m = fresh.exec(text)) !== null) matches.push(m[0]);
  return matches;
}

/**
 * Every unique token with how many times it's used and how many of those uses
 * have a fallback. A token is only covered when every use is: a fallback in
 * the greeting doesn't protect a bare use further down.
 */
export function analyseTokens(text, espKey) {
  const esp = ESPs[espKey];
  const tokenMap = new Map();
  for (const raw of findAll(text, esp.tokenRegex)) {
    const varName = esp.extractVar(raw);
    const covered = esp.detectFallback(raw, text);
    let t = tokenMap.get(varName);
    if (!t) {
      t = { raw, varName, count: 0, withFallback: 0, fallbackValue: null };
      tokenMap.set(varName, t);
    }
    t.count++;
    if (covered) t.withFallback++;
    if (!t.fallbackValue) t.fallbackValue = esp.getFallbackValue(raw);
  }
  const tokens = [...tokenMap.values()].map(t => ({ ...t, hasFallback: t.withFallback === t.count }));
  const openCount  = esp.ifOpenRegex  ? findAll(text, esp.ifOpenRegex).length  : 0;
  const closeCount = esp.ifCloseRegex ? findAll(text, esp.ifCloseRegex).length : 0;
  return { esp, tokens, openCount, closeCount };
}
